from pathlib import Path

ROOT = Path('/srv/imports')

def read_import(name: str) -> bytes:
    candidate = ROOT / name
    if not str(candidate).startswith(str(ROOT)):
        raise ValueError('outside root')
    return candidate.read_bytes()
