func (s *Store) Document(ctx context.Context, userID, documentID string) (*Document, error) {
    row := s.db.QueryRowContext(ctx, `SELECT id, user_id, title, body FROM documents WHERE id = ?`, documentID)
    var d Document
    if err := row.Scan(&d.ID, &d.UserID, &d.Title, &d.Body); err != nil {
        return nil, err
    }
    return &d, nil
}
